const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'P(-2,-3)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '第三象限' },
      { kind: 'text', payload: '-2' },
      { kind: 'text', payload: '-3' }
    ];
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 480;
    var H = (input && input.viewport && input.viewport.heightDu) || 400;
    var cx = Math.round(W / 2);
    var cy = Math.round(H / 2);
    var unit = Math.min(W, H) / 10;

    function r(v) { return Math.round(v * 100) / 100; }
    function seg(x1, y1, x2, y2) {
      return ['M ' + r(x1) + ' ' + r(y1), 'L ' + r(x2) + ' ' + r(y2)];
    }
    function dashed(x1, y1, x2, y2, dash, gap) {
      var out = [];
      var dx = x2 - x1, dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) { return out; }
      var ux = dx / len, uy = dy / len;
      var pos = 0;
      while (pos < len) {
        var s = Math.min(dash, len - pos);
        out.push('M ' + r(x1 + ux * pos) + ' ' + r(y1 + uy * pos));
        out.push('L ' + r(x1 + ux * (pos + s)) + ' ' + r(y1 + uy * (pos + s)));
        pos += dash + gap;
      }
      return out;
    }
    function mt(i, d) {
      var e = metrics && metrics[i];
      return (e && typeof e.width === 'number') ? e.width : d;
    }

    var px = cx - 2 * unit;
    var py = cy + 3 * unit;

    var ticks = [];
    var i;
    for (i = -4; i <= 4; i++) {
      if (i === 0) { continue; }
      var tx = cx + i * unit;
      if (tx > 34 && tx < W - 34) { ticks = ticks.concat(seg(tx, cy - 4, tx, cy + 4)); }
      var ty = cy + i * unit;
      if (ty > 34 && ty < H - 34) { ticks = ticks.concat(seg(cx - 4, ty, cx + 4, ty)); }
    }

    var xAxis = visualSdk.arrow(30, cy, W - 30, cy);
    var yAxis = visualSdk.arrow(cx, H - 30, cx, 30);
    var dot = visualSdk.circle(px, py, 4.5);
    var dashH = dashed(px, py, cx, py, 5, 4);
    var dashV = dashed(px, py, px, cy, 5, 4);

    var pw = mt(0, 44);
    var pLabelX = px + 10;
    if (pLabelX + pw > W - 6) { pLabelX = px - pw - 10; }

    return {
      schemaVersion: 1,
      sceneId: 'fig-quadrant3-point',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xaxis', commands: xAxis },
        { id: 'yaxis', commands: yAxis },
        { id: 'ticks', commands: ticks },
        { id: 'dashH', commands: dashH },
        { id: 'dashV', commands: dashV },
        { id: 'point', commands: dot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'xaxis', stroke: '#26354a', strokeWidth: 1.5, fill: 'none' },
          { type: 'path', pathId: 'yaxis', stroke: '#26354a', strokeWidth: 1.5, fill: 'none' },
          { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 1, fill: 'none' },
          { type: 'path', pathId: 'dashH', stroke: '#c0392b', strokeWidth: 1.2, fill: 'none' },
          { type: 'path', pathId: 'dashV', stroke: '#c0392b', strokeWidth: 1.2, fill: 'none' },
          { type: 'path', pathId: 'point', stroke: '#c0392b', strokeWidth: 1.5, fill: '#c0392b' },
          { type: 'label', text: 'O', x: cx - 12, y: cy + 16, fontSize: 14, anchor: 'middle', textAnchor: 'middle', fill: '#26354a' },
          { type: 'label', text: 'x', x: W - 22, y: cy + 18, fontSize: 14, anchor: 'middle', textAnchor: 'middle', fill: '#26354a' },
          { type: 'label', text: 'y', x: cx + 16, y: 34, fontSize: 14, anchor: 'middle', textAnchor: 'middle', fill: '#26354a' },
          { type: 'label', text: '-2', x: px, y: cy + 20, fontSize: 12, anchor: 'middle', textAnchor: 'middle', fill: '#26354a' },
          { type: 'label', text: '-3', x: cx - 16, y: py + 4, fontSize: 12, anchor: 'end', textAnchor: 'end', fill: '#26354a' },
          { type: 'label', text: 'P(-2,-3)', x: pLabelX, y: py + 18, fontSize: 14, anchor: 'start', textAnchor: 'start', fill: '#c0392b' },
          { type: 'label', text: '第三象限', x: cx - 2.7 * unit, y: cy + 1.3 * unit, fontSize: 13, anchor: 'middle', textAnchor: 'middle', fill: '#26354a' }
        ]
      }
    };
  }
};
